import os
import json
import pickle

import numpy as np
import pandas as pd
from flask import Flask, render_template, request, jsonify

from sklearn.model_selection import train_test_split
from sklearn.compose import ColumnTransformer
from sklearn.preprocessing import OneHotEncoder
from sklearn.pipeline import Pipeline
from sklearn.impute import SimpleImputer
from sklearn.linear_model import LinearRegression

app = Flask(__name__)

RANDOM_STATE = 42

# ─── Load pre-computed results (generated by code.py) ────────────────────────
def load_json(path, fallback=None):
    try:
        with open(path) as f:
            return json.load(f)
    except FileNotFoundError:
        return fallback


# ─── Re-train the full model in-memory so /predict works without pickling ────
_model_cache = {}

def get_full_model():
    if "model" in _model_cache:
        return _model_cache["model"]

    csv_path = r"C:\Users\user\Downloads\50_Startups.csv"
    df = pd.read_csv(csv_path)
    df.columns = df.columns.str.strip()

    numerical_features   = ["R&D Spend", "Administration", "Marketing Spend"]
    categorical_features = ["State"]
    all_features         = numerical_features + categorical_features
    target               = "Profit"

    X = df[all_features]
    y = df[target]
    X_train, _, y_train, _ = train_test_split(X, y, test_size=0.20,
                                               random_state=RANDOM_STATE)

    numeric_pipeline = Pipeline([("imputer", SimpleImputer(strategy="median"))])
    categorical_pipeline = Pipeline([
        ("imputer", SimpleImputer(strategy="most_frequent")),
        ("onehot", OneHotEncoder(drop="first", handle_unknown="ignore", sparse_output=False))
    ])
    preprocessor = ColumnTransformer([
        ("num", numeric_pipeline, numerical_features),
        ("cat", categorical_pipeline, categorical_features)
    ])

    model = Pipeline([
        ("preprocessor", preprocessor),
        ("regressor", LinearRegression())
    ])
    model.fit(X_train, y_train)
    _model_cache["model"] = model
    return model


# ─── Routes ──────────────────────────────────────────────────────────────────

@app.route("/")
def index():
    base_metrics   = load_json("results/base_metrics.json", {})
    rmse_by_n      = load_json("results/rmse_by_n.json", [])
    feature_sel    = load_json("results/feature_selection.json", [])

    # Convert best_subset lists to readable strings
    for row in rmse_by_n:
        if isinstance(row.get("best_subset"), list):
            row["best_subset_str"] = ", ".join(row["best_subset"])
        else:
            row["best_subset_str"] = str(row.get("best_subset", ""))

    return render_template(
        "index.html",
        base_metrics=base_metrics,
        rmse_by_n=rmse_by_n,
        feature_sel=feature_sel,
    )


@app.route("/predict", methods=["POST"])
def predict():
    try:
        data = request.get_json(force=True)
        rd_spend    = float(data.get("rd_spend", 0))
        admin       = float(data.get("admin", 0))
        marketing   = float(data.get("marketing", 0))
        state       = str(data.get("state", "New York"))

        model = get_full_model()
        sample = pd.DataFrame([{
            "R&D Spend":       rd_spend,
            "Administration":  admin,
            "Marketing Spend": marketing,
            "State":           state
        }])
        profit = float(model.predict(sample)[0])
        return jsonify({"success": True, "profit": round(profit, 2)})
    except Exception as e:
        return jsonify({"success": False, "error": str(e)})


@app.route("/api/rmse_data")
def api_rmse_data():
    data = load_json("results/rmse_by_n.json", [])
    return jsonify(data)


@app.route("/api/selection_data")
def api_selection_data():
    data = load_json("results/feature_selection.json", [])
    return jsonify(data)


if __name__ == "__main__":
    # Warm up the model on startup
    get_full_model()
    app.run(debug=True, port=5000)
